#include <iostream>
#include <cmath>

class Point {
private:
    double x;
    double y;

public:
    // Constructor
    Point(double xVal = 0.0, double yVal = 0.0) : x(xVal), y(yVal) {}

    // Getters
    double getX() const { return x; }
    double getY() const { return y; }

    // Setters
    void setX(double xVal) { x = xVal; }
    void setY(double yVal) { y = yVal; }

    // Calculate distance from origin
    double distanceFromOrigin() const {
        return std::sqrt(x * x + y * y);
    }

    // Calculate distance between this point and another
    double distanceTo(const Point& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        return std::sqrt(dx * dx + dy * dy);
    }

    // Overload the + operator for vector addition
    Point operator+(const Point& other) const {
        return Point(x + other.x, y + other.y);
    }

    // Overload the == operator for equality check
    bool operator==(const Point& other) const {
        return (x == other.x) && (y == other.y);
    }
};

int main() {
    Point p1(3.0, 4.0);
    Point p2(1.0, 1.0);

    std::cout << "Point 1: (" << p1.getX() << ", " << p1.getY() << ")" << std::endl;
    std::cout << "Distance from origin: " << p1.distanceFromOrigin() << std::endl;
    std::cout << "Distance to Point 2: " << p1.distanceTo(p2) << std::endl;

    Point p3 = p1 + p2;
    std::cout << "Sum of points: (" << p3.getX() << ", " << p3.getY() << ")" << std::endl;

    return 0;
}
